from docx import Document

doc = Document('/root/offer_letter_template.docx')

print("=== TEMPLATE STRUCTURE ===\n")
print("PARAGRAPHS:")
for i, paragraph in enumerate(doc.paragraphs):
    text = paragraph.text
    if text.strip():
        print(f"{i}: {repr(text)}")

print("\n\nTABLES:")
for t_idx, table in enumerate(doc.tables):
    print(f"\nTable {t_idx}:")
    for r_idx, row in enumerate(table.rows):
        print(f"  Row {r_idx}:")
        for c_idx, cell in row.cells:
            for p in cell.paragraphs:
                if p.text.strip():
                    print(f"    Cell {c_idx}: {repr(p.text)}")
